import {getChatGPTAuth} from '@/lib/auth/chatgpt';

export async function GET() {
  if (process.env.NODE_ENV !== 'development' || process.env.OPENAI_SIWC_CLIENT_ID !== 'oaiapp_mock') {
    return new Response(null, {status: 404});
  }
  const auth = getChatGPTAuth();
  if (!auth) return new Response(null, {status: 503});
  const origin = 'http://127.0.0.1:3600';
  const start = await auth.start(new Request(\`\${origin}/api/auth/chatgpt/start\`, {
    method: 'POST',
    headers: {origin},
  }));
  const authorization = new URL(start.headers.get('location') ?? '');
  const query = new URLSearchParams({
    state: authorization.searchParams.get('state') ?? '',
    code: authorization.searchParams.get('nonce') ?? '',
  });
  const callback = await auth.callback(new Request(\`\${origin}/api/auth/chatgpt/callback?\${query}\`, {
    headers: {cookie: start.headers.get('set-cookie')?.split(';')[0] ?? ''},
  }));
  const headers = new Headers({Location: '/api/auth/preview'});
  for (const cookie of callback.headers.getSetCookie()) headers.append('Set-Cookie', cookie);
  return new Response(null, {status: 303, headers});
}
