print(f"Audit: {len(logs)} logs, {len(screenshots)} screenshots and OCR, {len(traces)} traces, {len(env_files)} env files.")
print(f"Credential matches: {len(matches)}")
if matches:
    print("Affected artifacts: " + ", ".join(matches))
    raise SystemExit(1)
