const {generateKeyPairSync, randomBytes, sign} = require('node:crypto');

const issuer = 'https://auth.openai.com';
const {publicKey, privateKey} = generateKeyPairSync('rsa', {modulusLength: 2048});
const jwk = {...publicKey.export({format: 'jwk'}), kid: 'dev-mock'};
const encode = value => Buffer.from(JSON.stringify(value)).toString('base64url');
const jwtHeader = encode({alg: 'RS256', kid: jwk.kid});
const actualFetch = globalThis.fetch;
globalThis.fetch = async (input, init) => {
  const url = new URL(input instanceof Request ? input.url : input);
  if (url.origin !== issuer) return actualFetch(input, init);
  if (url.pathname === '/.well-known/openid-configuration') {
    return Response.json({
      issuer,
      authorization_endpoint: `${issuer}/authorize`,
      token_endpoint: `${issuer}/token`,
      revocation_endpoint: `${issuer}/revoke`,
      jwks_uri: `${issuer}/jwks`,
    });
  }
  if (url.pathname === '/jwks') return Response.json({keys: [jwk]});
  if (url.pathname === '/revoke') return new Response(null);
  if (url.pathname === '/token') {
    const params = init.body instanceof URLSearchParams ? init.body : new URLSearchParams(init.body);
    const now = Math.floor(Date.now() / 1000);
    const payload = encode({
      iss: issuer,
      aud: 'oaiapp_mock',
      sub: 'demo-session',
      nonce: params.get('code'),
      iat: now,
      exp: now + 3600,
      name: 'Demo account',
    });
    const input = `${jwtHeader}.${payload}`;
    const signature = sign('RSA-SHA256', Buffer.from(input), privateKey).toString('base64url');
    return Response.json({
      id_token: `${input}.${signature}`,
      access_token: `mock-only-access.${randomBytes(24).toString('base64url')}`,
      refresh_token: `mock-only-refresh.${randomBytes(24).toString('base64url')}`,
      token_type: 'Bearer',
      expires_in: 3600,
      scope: 'openid profile email offline_access resource.invoke chatgpt.tokens.use.direct',
    });
  }
  return new Response(null, {status: 404});
};
