assert.ok(authorize.origin === 'https://auth.openai.com', 'redirects to the expected issuer');
const transaction = start.headers.get('set-cookie').split(';')[0];

const query = new URLSearchParams({
  state: authorize.searchParams.get('state'),
  code: authorize.searchParams.get('nonce'),
});
const callback = await fetch(`${auth}/callback?${query}`, {
  headers: {cookie: transaction},
  redirect: 'manual',
});
assert.ok(callback.headers.get('location') === '/workspace', 'mock callback verification succeeds');
const cookie = callback.headers.getSetCookie().find(value => value.startsWith('betterlook-chatgpt='));
assert.ok(cookie?.includes('HttpOnly; SameSite=Lax') && !/Max-Age|Expires/.test(cookie), 'session cookie flags');
const cookiePair = cookie.split(';')[0];
const session = await fetch(`${auth}/session`, {headers: {cookie: cookiePair}});
const status = await session.json();
assert.ok(status.status === 'signed-in' && status.planEnabled && status.account === 'Demo account', 'GET session is signed in');
assert.ok(!('accessToken' in status) && !('refreshToken' in status), 'status excludes provider credentials');
if (process.argv.includes('--keep-session')) {
  await writeFile(new URL('./preview-cookie', import.meta.url), cookiePair, {mode: 0o600});
