// @exec: {"yield_time_ms": 1000}
const pageId=load("authTokenPage");
const dest="/Users/rushout/.paradev/worktrees/betterlook/auth/.screenshots";
for (const state of ["signed-out","signed-in"]) {
  const session=state==="signed-out"?{status:"signed-out",available:true}:{status:"signed-in",account:"Demo account",planEnabled:true};
  await tools.mcp__chrome_devtools__emulate({pageId,viewport:"760x380x1",colorScheme:"light"});
  const initScript=`(() => {
      const nativeFetch = window.fetch.bind(window);
      window.fetch = (input, init) => {
        if (typeof input === 'string' && input === '/api/auth/chatgpt/session') {
          return Promise.resolve(Response.json(${JSON.stringify(session)}));
        }
        return nativeFetch(input, init);
      };
    })()`;
  await tools.mcp__chrome_devtools__navigate_page({pageId,type:"url",url:"http://127.0.0.1:3600/auth-preview",initScript});
  const label=state==="signed-out"?"Connect OpenAI":"Using ChatGPT plan";
  const ready=await tools.mcp__chrome_devtools__wait_for({pageId,text:[label],timeout:6000});
  const uid=ready.content[0].text.match(new RegExp(`uid=(\\d+_\\d+) button "${label}"`))?.[1];
  if(!uid){text({state,missingTrigger:true});continue;}
  await tools.mcp__chrome_devtools__click({pageId,uid});
  for (const theme of ["light","dark"]) {
    await tools.mcp__chrome_devtools__emulate({pageId,viewport:"760x380x1",colorScheme:theme});
    const target=state==="signed-in"?"Demo account":"Use your existing plan for eligible requests.";
    const panel=await tools.mcp__chrome_devtools__wait_for({pageId,text:[target],timeout:6000});
    if(panel.isError){text({state,theme,panel:false});continue;}
    const computed=await tools.mcp__chrome_devtools__evaluate_script({pageId,function:`() => {
      const panel=document.querySelector('[role=dialog]');
      const button=panel.querySelector('[data-oai-siwc-button]');
      const field=panel.querySelector('input[type=password]');
      const fieldStyles=field && getComputedStyle(field.parentElement);
      const styles=button && getComputedStyle(button);
      return {panelBorder:getComputedStyle(panel).borderTopWidth,
        brandBackground:styles?.backgroundColor, brandText:styles?.color,
        brandEnabled:button?.disabled===false, logoLoaded:button?.querySelector('img')?.naturalWidth>0,
        fieldBorder:fieldStyles?.borderTopWidth, fieldEmpty:field?.value==='', dark:matchMedia('(prefers-color-scheme: dark)').matches};
    }`});
    text({state,theme,computed:computed.content[0].text.split("```")[1]?.trim()});
    const shot=await tools.mcp__chrome_devtools__take_screenshot({pageId});
    const png=shot.content.find(block=>block.type==="image");
    if(!png || !/^[A-Za-z0-9+/=]+$/.test(png.data)) {text({state,theme,screenshot:false});continue;}
    const filename=`auth-${state}-${theme}.png`;
    const saved=await tools.exec_command({cmd:`printf '%s' '${png.data}' | base64 -D > '${dest}/${filename}'`,max_output_tokens:200});
    text({filename,saved:saved.exit_code===0});
  }
}

